// Exchanges the authorization code for tokens and validates the ID token (signature, iss, aud,
// exp, nonce per FR-004), returning the identity claims needed to resolve/create the local user.
export async function exchangeCalieoAuthorizationCode(params: {
  callbackParams: URLSearchParams;
  codeVerifier: string;
  expectedNonce: string;
  redirectUri: string;
}): Promise<CalieoIdentity> {
  const as = await discoverCalieoIssuer();
  const client = getClient();
  const clientAuth = getClientAuth();

  const response = await oauth.authorizationCodeGrantRequest(
    as,
    client,
    clientAuth,
    params.callbackParams,
    params.redirectUri,
    params.codeVerifier
  );

  const tokenResponse = await oauth.processAuthorizationCodeResponse(as, client, response, {
    expectedNonce: params.expectedNonce,
    requireIdToken: true,
  });

  const claims = oauth.getValidatedIdTokenClaims(tokenResponse);
  const email = claims?.email;
  if (typeof email !== "string" || !email) {
    throw new Error("Calieo ID token is missing the email claim");
  }
  const name = typeof claims?.name === "string" && claims.name ? claims.name : email;
  return { email, name };
}

